1213 | 	/**
1214 | 	 * Query the terminal's default background color with OSC 11 (`ESC ] 11 ; ? BEL`).
1215 | 	 * @param timeoutMs Query timeout in milliseconds.
1216 | 	 * @returns Promise containing the parsed RGB color, or undefined if it times out or fails to parse.
1217 | 	 */
1218 | 	queryTerminalBackgroundColor({ timeoutMs }: { timeoutMs: number }): Promise<RgbColor | undefined> {
1219 | 		return new Promise((resolve) => {
1220 | 			const query: PendingOsc11BackgroundQuery = {
1221 | 				settled: false,
1222 | 				resolve,
1223 | 				timer: undefined,
1224 | 			};
1225 | 
1226 | 			query.timer = setTimeout(() => {
1227 | 				if (query.settled) {
1228 | 					return;
1229 | 				}
1230 | 				query.settled = true;
1231 | 				query.timer = undefined;
1232 | 				query.resolve?.(undefined);
1233 | 				query.resolve = undefined;
1234 | 			}, timeoutMs);
1235 | 			this.pendingOsc11BackgroundQueries.push(query);
1236 | 			this.pendingOsc11BackgroundReplies += 1;
1237 | 			this.terminal.write("\x1b]11;?\x07");
1238 | 		});
1239 | 	}
