1241 | 	/**
1242 | 	 * Query the terminal's color-scheme preference with DSR (`CSI ? 996 n`).
1243 | 	 * Terminals that support the color palette notification protocol reply with
1244 | 	 * `CSI ? 997 ; 1 n` for dark or `CSI ? 997 ; 2 n` for light.
1245 | 	 */
1246 | 	queryTerminalColorScheme({ timeoutMs }: { timeoutMs: number }): Promise<TerminalColorScheme | undefined> {
1247 | 		return new Promise((resolve) => {
1248 | 			let settled = false;
1249 | 			let timer: NodeJS.Timeout | undefined;
1250 | 			let unsubscribe: () => void = () => {};
1251 | 			const settle = (scheme: TerminalColorScheme | undefined) => {
1252 | 				if (settled) return;
1253 | 				settled = true;
1254 | 				if (timer) {
1255 | 					clearTimeout(timer);
1256 | 					timer = undefined;
1257 | 				}
1258 | 				unsubscribe();
1259 | 				resolve(scheme);
1260 | 			};
1261 | 
1262 | 			unsubscribe = this.onTerminalColorSchemeChange(settle);
1263 | 			timer = setTimeout(() => settle(undefined), timeoutMs);
1264 | 			this.terminal.write("\x1b[?996n");
1265 | 		});
1266 | 	}
